#include "targets/falcon_h1/falcon_h1_mamba.h"
#include "core/device.h"
#include "ops/linear_attention/falcon_mamba_ssd/falcon_mamba_ssd.h"
#include <cuda_bf16.h>
#include <cuda_runtime.h>
#include <cmath>
#include <climits>
#include <stdexcept>
namespace ninfer::targets::falcon_h1 { namespace {
constexpr int H=3072,PROJ=6680,CH=3584,HEADS=24,HD=128,DS=256,KERNEL=4;
__device__ __forceinline__ float silu(float x){return x/(1.0f+expf(-x));}
__device__ __forceinline__ float mup_scale(int r){return r<H?0.3535533905932738f:r<2*H?0.25f:r<2*H+256?0.1767766952966369f:r<2*H+512?0.5f:0.3535533905932738f;}
__global__ void project_one(const float*x,const __nv_bfloat16*w,float*y){int r=blockIdx.x*blockDim.x+threadIdx.x;if(r>=PROJ)return;float a=0;for(int k=0;k<H;k++)a=fmaf(x[k]*0.4166666666666667f,__bfloat162float(w[static_cast<long long>(r)*H+k]),a);y[r]=a*mup_scale(r);}
__global__ void project_rows(const float*x,const __nv_bfloat16*w,float*y,int T){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=T*PROJ)return;int t=i/PROJ,r=i%PROJ;float a=0;for(int k=0;k<H;k++)a=fmaf(x[static_cast<long long>(t)*H+k]*0.4166666666666667f,__bfloat162float(w[static_cast<long long>(r)*H+k]),a);y[static_cast<long long>(t)*PROJ+r]=a*mup_scale(r);}
__global__ void conv_one(const float*p,float*hist,const __nv_bfloat16*w,const __nv_bfloat16*bias,float*out){int c=blockIdx.x*blockDim.x+threadIdx.x;if(c>=CH)return;float v=p[H+c],*h=hist+static_cast<long long>(c)*3,a=0;for(int j=0;j<3;j++)a=h[j]*__bfloat162float(w[c*4+j])+a;a=v*__bfloat162float(w[c*4+3])+a;a+=__bfloat162float(bias[c]);out[c]=silu(a);h[0]=h[1];h[1]=h[2];h[2]=v;}
__global__ void conv_rows(const float*p,const float*init,const __nv_bfloat16*w,const __nv_bfloat16*bias,float*out,int T){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=T*CH)return;int t=i/CH,c=i%CH;const float*h=init+static_cast<long long>(c)*3;float a=0;for(int j=0;j<3;j++){int q=t+j-3;float v=q<0?h[q+3]:p[static_cast<long long>(q)*PROJ+H+c];a=fmaf(v,__bfloat162float(w[c*4+j]),a);}a=fmaf(p[static_cast<long long>(t)*PROJ+H+c],__bfloat162float(w[c*4+3]),a);a+=__bfloat162float(bias[c]);out[i]=silu(a);}
__global__ void conv_state_rows(const float*p,float*s,int T){int c=blockIdx.x*blockDim.x+threadIdx.x;if(c>=CH)return;float*h=s+static_cast<long long>(c)*3;for(int t=0;t<T;t++){h[0]=h[1];h[1]=h[2];h[2]=p[static_cast<long long>(t)*PROJ+H+c];}}
__global__ void split_one(const float*co,float*x,float*b,float*c){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<3072)x[i]=co[i];else if(i<3328)b[i-3072]=co[i];else if(i<3584)c[i-3328]=co[i];}
__global__ void split_rows(const float*co,float*x,float*b,float*c,int T){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=T*CH)return;int t=i/CH,j=i%CH;if(j<3072)x[static_cast<long long>(t)*3072+j]=co[i];else if(j<3328)b[static_cast<long long>(t)*512+j-3072]=co[i];else c[static_cast<long long>(t)*512+j-3328]=co[i];}
__global__ void bf16_to_float(const __nv_bfloat16*src,float*dst,int n){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n)dst[i]=__bfloat162float(src[i]);}
__global__ void process_one(const float*p,const __nv_bfloat16*db,const __nv_bfloat16*alog,float*dt,float*da){int h=blockIdx.x*blockDim.x+threadIdx.x;if(h>=HEADS)return;dt[h]=p[6656+h]+__bfloat162float(db[h]);dt[h]=dt[h]>20?dt[h]:log1pf(expf(dt[h]));float a=-expf(__bfloat162float(alog[h]));for(int d=0;d<HD;d++)for(int n=0;n<DS;n++)da[(static_cast<long long>(h)*HD+d)*DS+n]=expf(dt[h]*a);}
__global__ void expand_bc(const float*bc,float*b,float*c,int T){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=T*HEADS*DS)return;int n=i%DS,h=(i/DS)%HEADS,t=i/(HEADS*DS);(void)h;b[i]=bc[static_cast<long long>(t)*CH+3072+n];c[i]=bc[static_cast<long long>(t)*CH+3328+n];}
__global__ void process_rows(const float*p,const __nv_bfloat16*db,const __nv_bfloat16*alog,float*dt,float*a,float*decays,int T){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=T*HEADS)return;int t=i/HEADS,h=i%HEADS;float v=p[static_cast<long long>(t)*PROJ+6656+h]+__bfloat162float(db[h]);dt[i]=v>20?v:log1pf(expf(v));a[i]=-expf(__bfloat162float(alog[h]));for(int d=0;d<HD;d++)for(int q=0;q<DS;q++)decays[(static_cast<long long>(t)*HEADS+h)*HD*DS+d*DS+q]=expf(dt[i]*a[i]);}
__global__ void recurrent(const float*x,const float*b,const float*dt,const float*da,float*S){long long i=static_cast<long long>(blockIdx.x)*blockDim.x+threadIdx.x;if(i>=static_cast<long long>(HEADS)*HD*DS)return;int n=i%DS,h=(i/DS)/HD;S[i]=S[i]*da[i]+dt[h]*b[n]*x[(i/DS)];}
__global__ void raw_one(const float*x,const float*c,const __nv_bfloat16*D,const float*S,float*r){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=H)return;int h=i/HD;float a=0;for(int n=0;n<DS;n++)a+=S[static_cast<long long>(i)*DS+n]*c[n];r[i]=a+__bfloat162float(D[h])*x[i];}
__global__ void gate_one(const float*p,const float*r,float*g){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<H)g[i]=r[i]*silu(p[i]);}
__global__ void gate_rows(const float*p,const float*r,float*g,int T){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<T*H)g[i]=r[i]*silu(p[static_cast<long long>(i/H)*PROJ+i%H]);}
__global__ void raw_chunk_to_hd(const float*raw,float*out,int T){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<T*H)out[i]=raw[(static_cast<long long>(i/H)*HEADS+(i%H)/HD)*HD+i%HD];}
__global__ void norm_one(const float*x,float*y,const __nv_bfloat16*w){__shared__ float q[256];int tid=threadIdx.x;float a=0;for(int i=tid;i<H;i+=256)a+=x[i]*x[i];q[tid]=a;__syncthreads();for(int d=128;d;d>>=1){if(tid<d)q[tid]+=q[tid+d];__syncthreads();}float v=rsqrtf(q[0]/H+1.e-5f);for(int i=tid;i<H;i+=256)y[i]=x[i]*v*__bfloat162float(w[i]);}
__global__ void norm_rows(const float*x,float*y,const __nv_bfloat16*w,int T){int t=blockIdx.x,tid=threadIdx.x;if(t>=T)return;__shared__ float q[256];float a=0;for(int i=tid;i<H;i+=256){float v=x[static_cast<long long>(t)*H+i];a=fmaf(v,v,a);}q[tid]=a;__syncthreads();for(int d=128;d;d>>=1){if(tid<d)q[tid]+=q[tid+d];__syncthreads();}float v=rsqrtf(q[0]/H+1.e-5f);for(int i=tid;i<H;i+=256)y[static_cast<long long>(t)*H+i]=x[static_cast<long long>(t)*H+i]*v*__bfloat162float(w[i]);}
__global__ void out_one(const float*x,const __nv_bfloat16*w,float*y){int r=blockIdx.x*blockDim.x+threadIdx.x;if(r<H){float a=0;for(int k=0;k<H;k++)a+=__bfloat162float(w[static_cast<long long>(r)*H+k])*x[k];y[r]=a;}}
__global__ void out_rows(const float*x,const __nv_bfloat16*w,float*y,int T){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=T*H)return;int t=i/H,r=i%H;float a=0;for(int k=0;k<H;k++)a=fmaf(__bfloat162float(w[static_cast<long long>(r)*H+k]),x[static_cast<long long>(t)*H+k],a);y[i]=a;}
}
std::size_t mamba_decode_workspace_bytes(){return (PROJ+CH+3072+512+512+HEADS+HEADS*HD*DS+H*4)*sizeof(float);}
std::size_t mamba_decode_reference_workspace_bytes(){return mamba_decode_workspace_bytes();}
MambaDecodeWorkspace mamba_decode_workspace_view(float*base,std::size_t bytes){if(!base||bytes<mamba_decode_workspace_bytes())throw std::invalid_argument("Mamba workspace arena too small");MambaDecodeWorkspace w;std::size_t o=0;auto take=[&](std::size_t n){float*p=base+o;o+=n;return p;};w.projection=take(PROJ);w.conv_output=take(CH);w.x=take(3072);w.b=take(512);w.c=take(512);w.dt=take(HEADS);w.da=take(HEADS*HD*DS);w.raw_ssm=take(H);w.gated=take(H);w.gated_norm=take(H);w.output=take(H);w.bytes=bytes;return w;}
std::size_t mamba_prefill_workspace_bytes(std::size_t T){ if(T==0||T>static_cast<std::size_t>(INT_MAX))throw std::invalid_argument("invalid Falcon prefill T");std::size_t head=(T*(PROJ+CH+3072+512+512+2*HEADS*DS+HEADS+2*HEADS*HD*DS+H*4)+2*static_cast<std::size_t>(HEADS)*HD*DS+HEADS)*sizeof(float);return ((head+255)&~std::size_t(255))+ops::detail::falcon_mamba_ssd::workspace_bytes(T);}
MambaPrefillWorkspace mamba_prefill_workspace_view(float*base,std::size_t bytes,std::size_t T){ if(!base||bytes<mamba_prefill_workspace_bytes(T))throw std::invalid_argument("Falcon prefill workspace too small");MambaPrefillWorkspace w;std::size_t o=0;auto take=[&](std::size_t n){float*p=base+o;o+=n;return p;};w.projection=take(T*PROJ);w.conv_output=take(T*CH);w.x=take(T*3072);w.b=take(T*512);w.c=take(T*512);w.b_heads=take(T*HEADS*DS);w.c_heads=take(T*HEADS*DS);w.dt=take(T*HEADS);w.a=take(T*HEADS);w.dA=take(T*HEADS*HD*DS);w.decays=take(T*HEADS*HD*DS);w.raw_ssm=take(T*H);w.gated=take(T*H);w.gated_norm=take(T*H);w.output=take(T*H);w.d=take(HEADS);w.ssm_out=take(HEADS*HD*DS);w.ssd=base+((o+255)&~std::size_t(255));w.tokens=T;w.bytes=bytes;return w;}
std::size_t mamba_prefill_reference_workspace_bytes(std::size_t T){return mamba_prefill_workspace_bytes(T);}
void mamba_prefill(const BoundModel&model,const artifact::MaterializedArtifact&mat,std::size_t layer,const float*input,std::size_t T,MambaDecodeStateView state,MambaPrefillWorkspace w,MambaPrefillTaps taps,cudaStream_t stream){if(layer>=model.layer_count||!input||!state.compact_conv||!state.ssm||T==0||T>static_cast<std::size_t>(INT_MAX)||w.tokens!=T||!w.ssd||!w.ssm_out||w.bytes<mamba_prefill_workspace_bytes(T))throw std::invalid_argument("invalid Falcon Mamba prefill arguments/workspace");auto ptr=[&](const char*s){return static_cast<const __nv_bfloat16*>(mat.device_data(model.tensors.at("text/layers."+std::to_string(layer)+".mamba."+s).handle));};int n=T;project_rows<<<(n*PROJ+127)/128,128,0,stream>>>(input,ptr("in_proj.weight"),w.projection,n);CUDA_CHECK(cudaGetLastError());conv_rows<<<(n*CH+127)/128,128,0,stream>>>(w.projection,state.compact_conv,ptr("conv1d.weight"),ptr("conv1d.bias"),w.conv_output,n);CUDA_CHECK(cudaGetLastError());conv_state_rows<<<(CH+127)/128,128,0,stream>>>(w.projection,state.compact_conv,n);CUDA_CHECK(cudaGetLastError());split_rows<<<(n*CH+255)/256,256,0,stream>>>(w.conv_output,w.x,w.b,w.c,n);CUDA_CHECK(cudaGetLastError());expand_bc<<<(n*HEADS*DS+255)/256,256,0,stream>>>(w.conv_output,w.b_heads,w.c_heads,n);CUDA_CHECK(cudaGetLastError());process_rows<<<(n*HEADS+127)/128,128,0,stream>>>(w.projection,ptr("dt_bias"),ptr("A_log"),w.dt,w.a,w.dA,n);CUDA_CHECK(cudaGetLastError());bf16_to_float<<<1,32,0,stream>>>(ptr("D"),w.d,HEADS);CUDA_CHECK(cudaGetLastError());ops::detail::falcon_mamba_ssd::launch(w.x,w.b_heads,w.c_heads,w.dt,w.a,w.d,state.ssm,w.raw_ssm,w.ssm_out,n,w.ssd,ops::detail::falcon_mamba_ssd::workspace_bytes(n),stream);gate_rows<<<(n*H+255)/256,256,0,stream>>>(w.projection,w.raw_ssm,w.gated,n);CUDA_CHECK(cudaGetLastError());norm_rows<<<n,256,0,stream>>>(w.gated,w.gated_norm,ptr("norm.weight"),n);CUDA_CHECK(cudaGetLastError());out_rows<<<(n*H+127)/128,128,0,stream>>>(w.gated_norm,ptr("out_proj.weight"),w.output,n);CUDA_CHECK(cudaGetLastError());auto cp=[&](float*d,const float*s,std::size_t z){if(d)CUDA_CHECK(cudaMemcpyAsync(d,s,z*sizeof(float),cudaMemcpyDeviceToDevice,stream));};if(taps.in_proj)cp(taps.in_proj,w.projection,n*PROJ);if(taps.z)for(int t=0;t<n;t++)cp(taps.z+static_cast<std::size_t>(t)*H,w.projection+static_cast<std::size_t>(t)*PROJ,H);if(taps.xbc)for(int t=0;t<n;t++)cp(taps.xbc+static_cast<std::size_t>(t)*CH,w.projection+static_cast<std::size_t>(t)*PROJ+H,CH);if(taps.dt_split)for(int t=0;t<n;t++)cp(taps.dt_split+static_cast<std::size_t>(t)*HEADS,w.projection+static_cast<std::size_t>(t)*PROJ+2*H+512,HEADS);if(taps.conv)cp(taps.conv,w.conv_output,n*CH);if(taps.x)cp(taps.x,w.x,n*3072);if(taps.b)for(int t=0;t<n;t++)cp(taps.b+static_cast<std::size_t>(t)*256,w.b+static_cast<std::size_t>(t)*512,256);if(taps.c)for(int t=0;t<n;t++)cp(taps.c+static_cast<std::size_t>(t)*256,w.c+static_cast<std::size_t>(t)*512,256);if(taps.dt)cp(taps.dt,w.dt,n*HEADS);if(taps.A)cp(taps.A,w.a,n*HEADS);if(taps.dA)cp(taps.dA,w.dA,n*HEADS*HD*DS);if(taps.raw_ssm)cp(taps.raw_ssm,w.raw_ssm,n*H);if(taps.gated)cp(taps.gated,w.gated,n*H);if(taps.gated_norm)cp(taps.gated_norm,w.gated_norm,n*H);if(taps.out_proj)cp(taps.out_proj,w.output,n*H);if(taps.conv_state)cp(taps.conv_state,state.compact_conv,CH*3);if(taps.ssm_state)cp(taps.ssm_state,w.ssm_out,HEADS*HD*DS);}
float falcon_ssm_out_multiplier(){ return 1.0f; }
void mamba_decode(const BoundModel&model,const artifact::MaterializedArtifact&mat,std::size_t layer,const float*input,MambaDecodeStateView state,MambaDecodeWorkspace w,MambaDecodeTaps t,cudaStream_t stream){if(layer>=model.layer_count||!input||!state.compact_conv||!state.ssm||!w.projection||!w.conv_output||!w.x||!w.b||!w.c||!w.dt||!w.da||!w.raw_ssm||!w.gated||!w.gated_norm||!w.output||w.bytes<mamba_decode_workspace_bytes())throw std::invalid_argument("invalid Falcon Mamba decode arguments/workspace");auto ptr=[&](const char*s){return static_cast<const __nv_bfloat16*>(mat.device_data(model.tensors.at("text/layers."+std::to_string(layer)+".mamba."+s).handle));};project_one<<<(PROJ+127)/128,128,0,stream>>>(input,ptr("in_proj.weight"),w.projection);CUDA_CHECK(cudaGetLastError());conv_one<<<(CH+127)/128,128,0,stream>>>(w.projection,state.compact_conv,ptr("conv1d.weight"),ptr("conv1d.bias"),w.conv_output);CUDA_CHECK(cudaGetLastError());split_one<<<(CH+255)/256,256,0,stream>>>(w.conv_output,w.x,w.b,w.c);CUDA_CHECK(cudaGetLastError());process_one<<<(HEADS+31)/32,32,0,stream>>>(w.projection,ptr("dt_bias"),ptr("A_log"),w.dt,w.da);CUDA_CHECK(cudaGetLastError());recurrent<<<(HEADS*HD*DS+255)/256,256,0,stream>>>(w.x,w.b,w.dt,w.da,state.ssm);CUDA_CHECK(cudaGetLastError());raw_one<<<(H+255)/256,256,0,stream>>>(w.x,w.c,ptr("D"),state.ssm,w.raw_ssm);CUDA_CHECK(cudaGetLastError());gate_one<<<(H+255)/256,256,0,stream>>>(w.projection,w.raw_ssm,w.gated);CUDA_CHECK(cudaGetLastError());norm_one<<<1,256,0,stream>>>(w.gated,w.gated_norm,ptr("norm.weight"));CUDA_CHECK(cudaGetLastError());out_one<<<(H+127)/128,128,0,stream>>>(w.gated_norm,ptr("out_proj.weight"),w.output);CUDA_CHECK(cudaGetLastError());auto cp=[&](float*d,const float*s,std::size_t z){if(d)CUDA_CHECK(cudaMemcpyAsync(d,s,z*sizeof(float),cudaMemcpyDeviceToDevice,stream));};if(t.in_proj)cp(t.in_proj,w.projection,PROJ);if(t.z)cp(t.z,w.projection,H);if(t.xbc)cp(t.xbc,w.projection+H,CH);if(t.dt_split)cp(t.dt_split,w.projection+2*H+512,HEADS);if(t.conv)cp(t.conv,w.conv_output,CH);if(t.x)cp(t.x,w.x,3072);if(t.b)cp(t.b,w.b,256);if(t.c)cp(t.c,w.c+256,256);if(t.dt)cp(t.dt,w.dt,HEADS);if(t.da)cp(t.da,w.da,HEADS*HD*DS);if(t.raw_ssm)cp(t.raw_ssm,w.raw_ssm,H);if(t.gated)cp(t.gated,w.gated,H);if(t.gated_norm)cp(t.gated_norm,w.gated_norm,H);if(t.out_proj)cp(t.out_proj,w.output,H);if(t.conv_state)cp(t.conv_state,state.compact_conv,CH*3);if(t.ssm_state)cp(t.ssm_state,state.ssm,HEADS*HD*DS);}
}
